// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 blockTimestamp) public {
        vm.assume(blockTimestamp > 0);
        vm.assume(blockNum < type(uint256).max);
        vm.assume(blockTimestamp < type(uint256).max - 2);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.warp(blockTimestamp);
        vm.roll(blockNum);

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback reverted");

        if (blockNum % 15 == 0) {
            uint256 bal = address(c).balance;
            assertTrue(bal == 0);
        } else {
            uint256 bal = address(c).balance;
            assertTrue(bal == 10 ether);
        }
    }
}
